 for en,zh,loc,n in [('Catallus','卡塔鲁斯','篇0800','依核心 Catallus Rift 卡塔鲁斯裂隙；原卡图卢斯'),('Manushya-Rakshsasi','罗刹女','篇0800','色孽守密者专名，沿原稿'),('Dark Glass','黑暗琉璃','篇0800','网道装置，沿原稿'),('Madail','马代尔','篇0801','恶魔专名，沿原稿'),('Necrosphere','死灵圈','A0801-B0025','包围戴文的骸骨外壳，沿稿'),('Blade Encarmine','染赤之刃','A0801-B0033','圣吉列斯武器，沿原稿'),('Sthenelus','斯特涅洛斯号','A0801-B0027','钢铁之手巡洋舰'),('Samothrace','萨莫色雷斯号','A0801-B0031','本篇基里曼旗舰')]:f.write('\t'.join([en,zh,'暂定·官方待核','所给英文底稿',loc,n])+'\n')
